let named name = List.find (fun raw -> Json.string (get "name" raw) = name) fixtures
let operation raw = Json.string (get "operation" raw)
let run ?parent ?(executable=Protocol.Core) ?(request_id="protocol-literal") raw =
  K.handle ?parent ~executable ~request_id ~operation:(operation raw) (get "payload" raw)
let with_payload raw payload = set "payload" payload raw
let replay raw =
  let operation = operation raw in
  require (String.starts_with ~prefix:"verify-" operation) "Only verification fixtures can be replayed";
  set "operation" (str ("replay-" ^ String.sub operation 7 (String.length operation-7)))
    (with_payload raw (set "assessment" (get "assessment" (get "expected" raw)) (get "payload" raw)))
let defaults = get "default_limits" (get "realization" expected_profiles)
let reduction raw key value = with_payload raw (set "limits" (set key value defaults) (get "payload" raw))
let all_literal_routes () =
  require (List.length fixtures=36) "Independent protocol fixture census changed";
  require (Canonical.encode (Json.Object K.profiles) = Canonical.encode expected_profiles)
    "Capabilities differ from the independently frozen profile/resource contract";
  let seen = ref [] in
  List.iter (fun fixture ->
    let name = Json.string (get "name" fixture) in
    List.iter (fun executable ->
      let result = run ~executable fixture in
      require (Canonical.encode result = Canonical.encode (get "expected" fixture))
        (name ^ ": complete wrapper, authority, report, hash or scope differs");
      seen := operation fixture :: !seen;
      if String.starts_with ~prefix:"verify-" (operation fixture) then (
        let replay = replay fixture in
        require (Canonical.encode (run ~executable replay) = Canonical.encode result)
          (name ^ ": fresh replay changed a complete original report");
        seen := operation replay :: !seen)) [Protocol.Core;Protocol.Verify]) fixtures;
  require (List.sort_uniq String.compare !seen = List.sort String.compare K.operations)
    "An advertised operation lacked complete independent verification"
let malformed_controls () =
  let fixture = named "direct_baseline" in
  let payload = get "payload" fixture in
  let call payload = run (with_payload fixture payload) in
  rejected "missing_field" (fun () -> call (Json.Object (List.remove_assoc "profile" (Json.object_fields payload))));
  rejected "unknown_field" (fun () -> call (set "checker_version" (str "changed") payload));
  rejected "duplicate_key" (fun () -> call (Json.Object (("profile",get "profile" payload) :: Json.object_fields payload)));
  rejected "realization_protocol_profile" (fun () -> call (set "profile" (str "biocompiler.core.component_behavior.v1") payload));
  rejected "invalid_type" (fun () -> call (set "profile" (Json.Bool true) payload));
  List.iter (fun limits -> rejected "realization_limits" (fun () -> call (set "limits" limits payload)))
    [Json.Bool true;Json.Float 1.;Json.Array []];
  rejected "missing_field" (fun () -> call (set "limits" (Json.Object []) payload));
  rejected "unknown_field" (fun () -> call (set "limits" (set "extra" Json.Null defaults) payload));
  List.iter (fun (key,ceiling) ->
    List.iter (fun value -> rejected "realization_limits" (fun () -> run (reduction fixture key value)))
      [Json.Bool true;Json.Float 1.;Json.Null;Json.int 0;Json.int (-1);Json.int (ceiling+1);
       Json.Int (Z.pow (Z.of_int 10) 100)])
    ["max_work",50_000_000;"max_monitor_items",100_000;"max_request_bytes",Limits.max_request_bytes;
     "max_report_bytes",Limits.max_response_bytes;"max_report_nodes",Limits.max_json_nodes];
  rejected "invalid_type" (fun () -> call (set "until" (Json.Bool false) payload));
  List.iter (fun operation ->
    let fixture = set "operation" (str operation) fixture in
    rejected "realization_horizon" (fun () -> run (with_payload fixture (set "until" (Json.int (-1)) payload)));
    rejected "realization_horizon" (fun () -> run (with_payload fixture
      (set "until" (Json.Int (Z.pow (Z.of_int 10) 400)) payload))))
    ["verify-realization";"realization-dependencies"];
  rejected "invalid_type" (fun () -> call (set "behavior" Json.Null (set "until" (Json.int (-1)) payload)))
let replay_mutations () =
  List.iter (fun name ->
    let fixture = replay (named name) in
    let payload = get "payload" fixture in
    let assessment = get "assessment" payload in
    let dependencies = get "dependencies" assessment in
    let dependencies = if name = "assembly_baseline" then set "request" (str (String.make 64 '0')) dependencies
      else set "checker" (str "changed.v999") dependencies in
    let changed = set "dependencies" dependencies assessment in
    rejected "realization_assessment_mismatch" (fun () -> run (with_payload fixture (set "assessment" changed payload))))
    ["direct_baseline";"synthetic_baseline";"component_baseline";"assembly_baseline"];
  let fixture = replay (named "direct_baseline") in
  let payload = get "payload" fixture and assessment = get "assessment" (get "payload" fixture) in
  rejected "unknown_field" (fun () -> run (with_payload fixture
    (set "assessment" (set "imported_pass" (Json.Bool true) assessment) payload)));
  let dependencies = get "dependencies" assessment in
  let horizon = set "until" (Json.Float 7.) (get "horizon" dependencies) in
  let changed = set "dependencies" (set "horizon" horizon dependencies) assessment in
  rejected "realization_assessment_mismatch" (fun () -> run (with_payload fixture (set "assessment" changed payload)));
  let changed = set "outcome" (str "fail") assessment in
  rejected "realization_assessment_mismatch" (fun () -> run (with_payload fixture (set "assessment" changed payload)));
  let behavior = get "behavior" payload in
  let relocate values = Json.array values |> List.map (fun node ->
      match get "source" node with Json.Null -> node | source ->
        set "source" (set "file" (str "moved_來源.py") source) node) |> fun values -> Json.Array values in
  let behavior = set "nodes" (relocate (get "nodes" behavior))
      (set "requirements" (relocate (get "requirements" behavior)) behavior) in
  rejected "realization_assessment_mismatch" (fun () -> run (with_payload fixture
    (set "behavior" behavior payload)));
  require (Canonical.encode (run (named "direct_baseline")) =
      Canonical.encode (get "expected" (named "direct_baseline"))) "Replay failure leaked into a later call"
let authority_distinctions () =
  let fixture = named "dependencies_baseline" in
  let normal = run fixture in
  let explicit = run (with_payload fixture (set "limits" defaults (get "payload" fixture))) in
  require (Json.equal (get "dependencies" normal) (get "dependencies" explicit)) "Explicit defaults changed semantic dependencies";
  require (not (Json.equal (get "supplied_authority_fingerprint" normal) (get "supplied_authority_fingerprint" explicit)))
    "Supplied null and explicit default controls lost their raw authority distinction";
  let source = named "dependencies_unicode_baseline" in
  let result = run source in
  let payload = get "payload" source in
  let identities = get "authority_identities" result in
  require (Json.string (get "behavior_artifact_ascii_fingerprint" identities) <>
      Canonical.fingerprint (get "behavior" payload)) "Unicode Behavior ASCII identity collapsed into UTF-8";
  let numeric = named "dependencies_numeric_shorthand_negative_zero" in
  let result = run numeric in
  require (Json.string (get "history_ascii_fingerprint" (get "authority_identities" result)) <>
      Legacy_ascii.fingerprint (get "history" (get "payload" numeric)))
    "Numeric shorthand was not normalized for the history dependency identity";
  let payload = get "payload" numeric in
  let frames = Json.array (get "history" payload) in
  let positive = match frames with [] -> assert false | first :: rest -> set "time" (Json.Float 0.) first :: rest in
  let positive = run (with_payload numeric (set "history" (Json.Array positive) payload)) in
  require (not (Json.equal (get "supplied_authority_fingerprint" result) (get "supplied_authority_fingerprint" positive)))
    "Signed zero was erased from supplied authority"
let resource_boundaries () =
  let fixture = named "dependencies_baseline" in
  let operation = operation fixture and payload = get "payload" fixture in
  let _,usage = K.handle_with_usage ~executable:Protocol.Core ~request_id:"protocol-literal" ~operation payload in
  let parent maximum = W.create ~profile:"protocol.literal.parent" ~error_code:"protocol_parent_limit" ~maximum () in
  let exact = parent usage.work_charged in
  require (Json.equal (run ~parent:exact fixture) (get "expected" fixture) && W.remaining exact=0)
    "Exact ancestor work omitted framing, import, dependencies or publication";
  let short = parent (usage.work_charged-1) in
  (match run ~parent:short fixture with
   | _ -> failwith "One-under ancestor returned a result"
   | exception Diagnostic.Error error -> require (error.code="protocol_parent_limit" && W.is_exhaustion short error)
       "Publication masked ancestor exhaustion identity");
  let empty = parent 0 in
  rejected "protocol_parent_limit" (fun () -> run ~parent:empty fixture);
  List.iter (fun (key,code) -> rejected code (fun () -> run (reduction fixture key (Json.int 1))))
    ["max_work","realization_work_limit";"max_request_bytes","realization_input_limit";
     "max_report_bytes","realization_report_limit";"max_report_nodes","realization_report_limit";
     "max_monitor_items","realization_monitor_limit"];
  (* The chosen limit is itself part of authority and publication; find the
     exact actual boundary without assuming those records have constant size. *)
  List.iter (fun (key,maximum,code) ->
    let passes value = match run (reduction fixture key (Json.int value)) with
      | _ -> true | exception Diagnostic.Error error ->
          require (error.code=code) (key ^ ": unexpected boundary error " ^ error.code); false in
    let rec narrow low high = if high-low<=1 then high else
      let middle = low+(high-low)/2 in if passes middle then narrow low middle else narrow middle high in
    let threshold = narrow 1 maximum in
    require (passes threshold && not (passes (threshold-1))) (key ^ ": exact boundary not preserved"))
    ["max_work",50_000_000,"realization_work_limit";
     "max_request_bytes",Limits.max_request_bytes,"realization_input_limit";
     "max_report_bytes",Limits.max_response_bytes,"realization_report_limit";
     "max_report_nodes",Limits.max_json_nodes,"realization_report_limit"];
  let long_id = String.make 4096 'x' in
  let _,long_usage = K.handle_with_usage ~executable:Protocol.Verify ~request_id:long_id ~operation payload in
  require (long_usage.work_charged > usage.work_charged && long_usage.report_bytes > usage.report_bytes)
    "Actual request ID omitted from publication or ancestor work";
  rejected "string_limit" (fun () -> run ~request_id:(String.make (Limits.max_string_bytes+1) 'x') fixture);
  let rec cyclic = Json.Array [cyclic] in
  rejected "nesting_limit" (fun () -> run (with_payload fixture (set "history" cyclic payload)));
  let rec spine = Json.Null :: spine in
  rejected "node_limit" (fun () -> run (with_payload fixture (set "history" (Json.Array spine) payload)));
  let rec fields = ("loop",Json.Null) :: fields in
  rejected "node_limit" (fun () -> run (with_payload fixture (set "history" (Json.Object fields) payload)));
  require (Canonical.encode (run fixture) = Canonical.encode (get "expected" fixture))
    "Resource failure changed a later operation"
let () =
  all_literal_routes ();
  malformed_controls ();
  replay_mutations ();
  authority_distinctions ();
  resource_boundaries ();
  print_endline "Independent realization protocol literals, complete replays, scopes and resource boundaries passed"
